import { useEffect, useState } from 'react';

function Checkout() {
  const [order, setOrder] = useState(null);
  const [method, setMethod] = useState(null);
  const [paymentId, setPaymentId] = useState(null);
  const [status, setStatus] = useState('idle');
  const [vpa, setVpa] = useState('');
  const [card, setCard] = useState({
    number: '',
    expiry: '',
    cvv: '',
    name: ''
  });

  const params = new URLSearchParams(window.location.search);
  const orderId = params.get('order_id');

  /* Fetch order */
  useEffect(() => {
    if (!orderId) return;

    fetch(`http://localhost:8000/api/v1/orders/${orderId}/public`)
      .then(res => res.json())
      .then(data => setOrder(data))
      .catch(() => setStatus('error'));
  }, [orderId]);

  /* Poll payment */
  useEffect(() => {
    if (!paymentId) return;

    const interval = setInterval(() => {
      fetch(`http://localhost:8000/api/v1/payments/${paymentId}/public`)
        .then(res => res.json())
        .then(data => {
          if (data.status === 'success' || data.status === 'failed') {
            setStatus(data.status);
            clearInterval(interval);
          }
        });
    }, 2000);

    return () => clearInterval(interval);
  }, [paymentId]);

  /* Create payment */
  const handlePayment = (e) => {
    e.preventDefault();
    setStatus('processing');

    const payload = { order_id: orderId, method };

    if (method === 'upi') payload.vpa = vpa;

    if (method === 'card') {
      const [month, year] = card.expiry.split('/');
      payload.card = {
        number: card.number,
        expiry_month: month,
        expiry_year: year,
        cvv: card.cvv,
        holder_name: card.name
      };
    }

    fetch('http://localhost:8000/api/v1/payments/public', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    })
      .then(res => res.json())
      .then(data => setPaymentId(data.id))
      .catch(() => setStatus('error'));
  };

  /* 🔴 NO BLANK PAGE EVER */
  if (!order) {
    return (
      <div style={{ textAlign: 'center', marginTop: '80px' }}>
        Loading order...
      </div>
    );
  }

  return (
    <div
      data-test-id="checkout-container"
      style={{
        maxWidth: '420px',
        margin: '60px auto',
        padding: '28px',
        background: '#ffffff',
        borderRadius: '12px',
        boxShadow: '0 10px 25px rgba(0,0,0,0.08)',
        fontFamily: 'Inter, Arial, sans-serif'
      }}
    >

      {/* Order Summary */}
      <div data-test-id="order-summary" style={{ marginBottom: '24px' }}>
        <h2>Complete Payment</h2>
        <div>
          <span>Amount: </span>
          <span data-test-id="order-amount">
            ₹{(order.amount / 100).toFixed(2)}
          </span>
        </div>
        <div>
          <span>Order ID: </span>
          <span data-test-id="order-id">{order.id}</span>
        </div>
      </div>

      {/* Payment Methods */}
      {status === 'idle' && (
        <div data-test-id="payment-methods">
          <button
            data-test-id="method-upi"
            onClick={() => setMethod('upi')}
            style={{ width: '100%', padding: '12px', marginBottom: '10px' }}
          >
            UPI
          </button>

          <button
            data-test-id="method-card"
            onClick={() => setMethod('card')}
            style={{ width: '100%', padding: '12px' }}
          >
            Card
          </button>
        </div>
      )}

      {/* UPI */}
      {method === 'upi' && status === 'idle' && (
        <form data-test-id="upi-form" onSubmit={handlePayment}>
          <input
            data-test-id="vpa-input"
            placeholder="username@bank"
            value={vpa}
            onChange={e => setVpa(e.target.value)}
          />
          <button data-test-id="pay-button" type="submit">
            Pay ₹{order.amount / 100}
          </button>
        </form>
      )}

      {/* Card */}
      {method === 'card' && status === 'idle' && (
        <form data-test-id="card-form" onSubmit={handlePayment}>
          <input data-test-id="card-number-input" placeholder="Card Number"
            value={card.number}
            onChange={e => setCard({ ...card, number: e.target.value })}
          />
          <input data-test-id="expiry-input" placeholder="MM/YY"
            value={card.expiry}
            onChange={e => setCard({ ...card, expiry: e.target.value })}
          />
          <input data-test-id="cvv-input" placeholder="CVV"
            value={card.cvv}
            onChange={e => setCard({ ...card, cvv: e.target.value })}
          />
          <input data-test-id="cardholder-name-input" placeholder="Name on Card"
            value={card.name}
            onChange={e => setCard({ ...card, name: e.target.value })}
          />
          <button data-test-id="pay-button" type="submit">
            Pay ₹{order.amount / 100}
          </button>
        </form>
      )}

      {/* Processing */}
      {status === 'processing' && (
        <div data-test-id="processing-state">
          <span data-test-id="processing-message">Processing payment...</span>
        </div>
      )}

      {/* Success */}
      {status === 'success' && (
        <div data-test-id="success-state">
          <h2>Payment Successful!</h2>
          <span data-test-id="payment-id">{paymentId}</span>
        </div>
      )}

      {/* Error */}
      {(status === 'failed' || status === 'error') && (
        <div data-test-id="error-state">
          <span data-test-id="error-message">
            Payment could not be processed
          </span>
          <button data-test-id="retry-button" onClick={() => window.location.reload()}>
            Try Again
          </button>
        </div>
      )}
    </div>
  );
}

export default Checkout;
